#!/usr/bin/env bash
# ---------------------------------------------------------------------------
# 0085 — Daftar kelayakan pengajar, periode "Batch Oktober 2026"
#
# Menyemai ks_kelayakan dari dropdown "Nama Lengkap Pengajar" di form Google:
# 37 ikhwan + 76 akhwat boleh mengisi, sisanya tidak.
# Setelah ini daftar dikelola koordinator lewat /ketersediaan/koordinator.
#
# Jalankan dari root repo SETELAH kode ter-deploy. Idempoten: aman diulang.
# Satu statement per panggilan — statement berat membuat prod 502 dan rollback.
# ---------------------------------------------------------------------------
set -euo pipefail
db() { npm run -s db -- --confirm "$1"; }

# ---- DDL ----
db "CREATE TABLE IF NOT EXISTS ks_kelayakan (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), periode_id uuid NOT NULL REFERENCES ks_periode(id) ON DELETE CASCADE, pengajar_id uuid NOT NULL REFERENCES pengajar(id) ON DELETE CASCADE, boleh boolean NOT NULL DEFAULT true, alasan text, diubah_oleh text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now())"
db "CREATE UNIQUE INDEX IF NOT EXISTS ks_kelayakan_periode_id_pengajar_id_key ON ks_kelayakan(periode_id, pengajar_id)"
db "CREATE INDEX IF NOT EXISTS idx_ks_kelayakan_periode ON ks_kelayakan(periode_id, boleh)"

